CREATE TABLE IF NOT EXISTS users(id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','teacher','student') NOT NULL,phone VARCHAR(30) DEFAULT '',subject VARCHAR(100) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,schedule VARCHAR(150) NOT NULL,fee DECIMAL(10,2) NOT NULL,teacher_id INT NULL,FOREIGN KEY(teacher_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS students(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL UNIQUE,class_id INT NOT NULL,parent_phone VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS payments(student_id INT NOT NULL,month CHAR(7) NOT NULL,amount DECIMAL(10,2) NOT NULL,paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(student_id,month),FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS attendance(student_id INT NOT NULL,class_id INT NOT NULL,session_date DATE NOT NULL,present BOOLEAN NOT NULL,PRIMARY KEY(student_id,class_id,session_date),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS materials(id INT PRIMARY KEY AUTO_INCREMENT,class_id INT NOT NULL,name VARCHAR(150) NOT NULL,type ENUM('PDF','Video') NOT NULL,filename VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,mime VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS notifications(id INT PRIMARY KEY AUTO_INCREMENT,student_id INT NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id));
